typedef unsigned long long u_long;

struct tGS_PMODE { u_long EN1:1, EN2:1, CRTMD:3, MMOD:1, AMOD:1, SLBG:1, ALP:8, _pad:48; };
struct tGS_SMODE2 { u_long INT:1, FFMD:1, DPMS:2, _pad:60; };
struct tGS_DISPFB2 { u_long FBP:9, FBW:6, PSM:5, _pad0:12, DBX:11, DBY:11, _pad1:10; };
struct tGS_DISPLAY2 { u_long DX:12, DY:11, MAGH:4, MAGV:2, _pad0:3, DW:12, DH:11, _pad1:9; };
struct tGS_BGCOLOR { u_long R:8, G:8, B:8, _pad:40; };
typedef tGS_DISPFB2 tGS_DISPFB1;
typedef tGS_DISPLAY2 tGS_DISPLAY1;
struct sceGsDispEnv;
extern "C" void sceGsSetDefDispEnv(sceGsDispEnv*, int, int, int, int, int);
extern unsigned int nglDisplayWidth;
extern unsigned int nglDisplayHeight;

#define NGL_FRAME_FORMAT 0
#define NGL_VRAM_FRAME1 0
#define NGL_VRAM_FRAME2 0xE00
#define DPUT_GS_PMODE(v) (*(volatile u_long*)0x12000000 = (v))
#define DPUT_GS_SMODE2(v) (*(volatile u_long*)0x12000020 = (v))
#define DPUT_GS_DISPFB1(v) (*(volatile u_long*)0x12000070 = (v))
#define DPUT_GS_DISPLAY1(v) (*(volatile u_long*)0x12000080 = (v))
#define DPUT_GS_DISPFB2(v) (*(volatile u_long*)0x12000090 = (v))
#define DPUT_GS_DISPLAY2(v) (*(volatile u_long*)0x120000A0 = (v))
#define DPUT_GS_BGCOLOR(v) (*(volatile u_long*)0x120000E0 = (v))

struct nglDisplayEnv
{
  tGS_PMODE pmode;
  tGS_SMODE2 smode2;
  tGS_DISPFB2 dispfb;
  tGS_DISPLAY2 display;
  tGS_BGCOLOR bgcolor;

  // extra registers
  tGS_DISPFB1 dispfb1;
  tGS_DISPLAY1 display1;
  tGS_DISPLAY1 pad;
} __attribute__ ((aligned(64)));

void nglSetDisplayEnv( int frame, int fsaa )
{
  nglDisplayEnv disp;
  sceGsSetDefDispEnv((sceGsDispEnv*)&disp, NGL_FRAME_FORMAT, nglDisplayWidth, nglDisplayHeight, 0, 0 ); // dx,dy = 0

  disp.dispfb.FBP = frame == 0 ? ( NGL_VRAM_FRAME1 / 32 ) : ( NGL_VRAM_FRAME2 / 32 );

  // set up 2 circuit antialiasing
  *(u_long*)&disp.dispfb1 = *(u_long*)&disp.dispfb;
  *(u_long*)&disp.display1 = *(u_long*)&disp.display;

  disp.dispfb.DBY = 1; // dispfb2 has DBY field of 1
  disp.display.DH = disp.display1.DH - 1;
  disp.display.DX = disp.display.DX + 2; // display2 has magh/2
  disp.pmode.ALP = 0x80;

  // toggle FSAA
  disp.pmode.EN1 = fsaa;
  disp.pmode.EN2 = 1;

  // write registers to GS.
  DPUT_GS_PMODE( *(u_long*)&disp.pmode );
  DPUT_GS_SMODE2( *(u_long*)&disp.smode2 );
  DPUT_GS_DISPFB2( *(u_long*)&disp.dispfb );
  DPUT_GS_DISPLAY2( *(u_long*)&disp.display );
  DPUT_GS_BGCOLOR( *(u_long*)&disp.bgcolor );

  DPUT_GS_DISPLAY1( *(u_long*)&disp.display1 );
  DPUT_GS_DISPFB1( *(u_long*)&disp.dispfb1 );
}
